package com.bank.column.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDateTime;

@Entity
@Table(name = "accounts")
public class Account {

    @Id
    @Column(name = "account_id")
    private String accountId;

    // name + nullable + length
    @Column(name = "holder_name", nullable = false, length = 100)
    private String holderName;

    // unique + length — storage-level uniqueness guarantee
    @Column(name = "pan", nullable = false, unique = true, length = 10)
    private String pan;

    // precision + scale → DECIMAL(15,2) — correct for money (never length for BigDecimal)
    @Column(name = "balance", nullable = false, precision = 15, scale = 2)
    private BigDecimal balance;

    @Column(name = "hold_amount", nullable = false, precision = 15, scale = 2)
    private BigDecimal holdAmount;

    // updatable=false → written on INSERT, never on UPDATE (opened-on date stays fixed)
    @Column(name = "created_at", updatable = false)
    private LocalDateTime createdAt;

    // JPA @Transient → NOT mapped to any column; computed in memory only
    @Transient
    private BigDecimal availableForWithdrawal;

    // Java transient keyword → skipped by Java Serializable ONLY.
    // Also @Transient so it is excluded from the DATABASE (keyword alone would NOT exclude it!)
    @Transient
    private transient String sessionCache;

    protected Account() {}

    public Account(String accountId, String holderName, String pan, BigDecimal balance, BigDecimal holdAmount) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.pan = pan;
        this.balance = balance;
        this.holdAmount = holdAmount;
        this.createdAt = LocalDateTime.now();
    }

    // Recompute the transient derived value after load and after construction
    @PostLoad
    @PostPersist
    void computeAvailable() {
        this.availableForWithdrawal = balance.subtract(holdAmount);
    }

    public String getAccountId() { return accountId; }
    public String getHolderName() { return holderName; }
    public String getPan() { return pan; }
    public BigDecimal getBalance() { return balance; }
    public BigDecimal getHoldAmount() { return holdAmount; }
    public LocalDateTime getCreatedAt() { return createdAt; }

    public BigDecimal getAvailableForWithdrawal() {
        // ensure it is computed even if @PostLoad hasn't run (e.g. freshly constructed)
        if (availableForWithdrawal == null) computeAvailable();
        return availableForWithdrawal;
    }

    public void setSessionCache(String sessionCache) { this.sessionCache = sessionCache; }
    public String getSessionCache() { return sessionCache; }
}
