package com.bank.column.service;

import com.bank.column.dto.AccountView;
import com.bank.column.model.Account;
import com.bank.column.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
@RequiredArgsConstructor
@Slf4j
public class AccountService {

    private final AccountRepository accountRepo;

    @Transactional
    public AccountView open(String accountId, String holderName, String pan,
                             BigDecimal balance, BigDecimal holdAmount) {
        Account account = new Account(accountId, holderName, pan, balance, holdAmount);
        account.setSessionCache("transient-scratch-not-stored"); // Java transient + @Transient
        accountRepo.save(account);
        // SQL INSERT includes: account_id, holder_name, pan, balance, hold_amount, created_at
        // SQL INSERT EXCLUDES: availableForWithdrawal, sessionCache (both @Transient)
        log.info("Opened {} balance=Rs.{} available=Rs.{} (available is @Transient, NOT a column)",
            accountId, account.getBalance(), account.getAvailableForWithdrawal());
        return AccountView.from(account);
    }

    @Transactional(readOnly = true)
    public AccountView view(String accountId) {
        Account account = accountRepo.findById(accountId).orElseThrow();
        // @PostLoad recomputed availableForWithdrawal from the two stored columns
        log.info("Loaded {} — availableForWithdrawal computed via @PostLoad = Rs.{}",
            accountId, account.getAvailableForWithdrawal());
        return AccountView.from(account);
    }
}
