package com.bank.column.controller;

import com.bank.column.dto.AccountView;
import com.bank.column.service.AccountService;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;

@RestController
@RequestMapping("/api/v1/accounts")
@RequiredArgsConstructor
public class AccountController {

    private final AccountService service;

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public AccountView open(@RequestParam String accountId, @RequestParam String holderName,
                             @RequestParam String pan, @RequestParam BigDecimal balance,
                             @RequestParam(defaultValue = "0") BigDecimal holdAmount) {
        return service.open(accountId, holderName, pan, balance, holdAmount);
    }

    @GetMapping("/{accountId}")
    public AccountView view(@PathVariable String accountId) {
        return service.view(accountId);
    }
}
