package com.bank.column.model;

import org.junit.jupiter.api.Test;
import java.lang.reflect.Field;
import java.math.BigDecimal;
import jakarta.persistence.Column;
import jakarta.persistence.Transient;
import static org.assertj.core.api.Assertions.*;

class ColumnMappingTest {

    @Test
    void balanceUsesPrecisionAndScale() throws Exception {
        Field balance = Account.class.getDeclaredField("balance");
        Column c = balance.getAnnotation(Column.class);
        assertThat(c.precision()).isEqualTo(15);
        assertThat(c.scale()).isEqualTo(2); // DECIMAL(15,2) for money
    }

    @Test
    void createdAtIsNotUpdatable() throws Exception {
        Field createdAt = Account.class.getDeclaredField("createdAt");
        Column c = createdAt.getAnnotation(Column.class);
        assertThat(c.updatable()).isFalse(); // set on INSERT, never on UPDATE
    }

    @Test
    void availableIsJpaTransient() throws Exception {
        Field available = Account.class.getDeclaredField("availableForWithdrawal");
        assertThat(available.isAnnotationPresent(Transient.class)).isTrue(); // excluded from DB
        assertThat(available.isAnnotationPresent(Column.class)).isFalse();
    }

    @Test
    void computedAvailableIsBalanceMinusHold() {
        Account a = new Account("SAV2001", "Rajesh Kumar", "ABCDE1234F",
            new BigDecimal("1000000.00"), new BigDecimal("50000.00"));
        assertThat(a.getAvailableForWithdrawal()).isEqualByComparingTo("950000.00");
    }

    @Test
    void javaTransientKeywordDoesNotExcludeFromDb() throws Exception {
        // The Java 'transient' keyword affects Java Serializable ONLY.
        // sessionCache is excluded from the DB because it ALSO has @Transient — not because of the keyword.
        Field sessionCache = Account.class.getDeclaredField("sessionCache");
        boolean keywordTransient = java.lang.reflect.Modifier.isTransient(sessionCache.getModifiers());
        assertThat(keywordTransient).isTrue();                         // keyword present
        assertThat(sessionCache.isAnnotationPresent(Transient.class)).isTrue(); // @Transient is what excludes it from DB
    }
}
